<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: 'Helvetica', Arial, sans-serif; color: #2d3748; font-size: 12px; background:#fff; }

        .top-stripe  { background:#212529; height:8px; width:100%; }
        .gold-stripe { background:#ffc800; height:4px; width:100%; }

        .page { padding: 36px 48px 40px; }

        /* HEADER */
        .logo-icon {
            background:#212529; color:#ffc800;
            font-size:20px; font-weight:900;
            padding:10px 16px; letter-spacing:1px;
            border-radius:4px; display:inline-block;
        }
        .logo-sub { display:block; color:#a0aec0; font-size:9px; letter-spacing:2px; text-transform:uppercase; margin-top:5px; }
        .ref-label  { font-size:9px; text-transform:uppercase; letter-spacing:2px; color:#a0aec0; }
        .ref-number { font-size:20px; font-weight:700; color:#212529; margin:3px 0; }
        .ref-date   { font-size:11px; color:#718096; }

        .gold-divider { border:none; border-top:2px solid #ffc800; margin:20px 0 24px; }

        /* BADGES STATUT */
        .badge { display:inline-block; padding:3px 12px; border-radius:20px; font-size:9px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; }
        .badge-payee   { background:#d1fae5; color:#065f46; border:1px solid #6ee7b7; }
        .badge-attente { background:#fef3c7; color:#92400e; border:1px solid #fcd34d; }
        .badge-annulee { background:#fee2e2; color:#991b1b; border:1px solid #fca5a5; }

        /* INFO BOXES */
        .info-label { font-size:8px; font-weight:700; text-transform:uppercase; letter-spacing:2px; color:#a0aec0; padding-bottom:5px; border-bottom:1px solid #e2e8f0; margin-bottom:8px; }
        .info-content { font-size:11px; color:#4a5568; line-height:1.8; }
        .info-content strong { color:#1a202c; font-size:12px; }

        /* TABLEAU */
        .details-table { width:100%; border-collapse:collapse; margin-bottom:24px; }
        .details-table thead tr { background:#212529; color:#fff; }
        .details-table thead th { padding:10px 14px; font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:1.5px; }
        .details-table thead th:first-child { border-radius:4px 0 0 4px; }
        .details-table thead th:last-child  { border-radius:0 4px 4px 0; }
        .details-table tbody td { padding:13px 14px; font-size:11.5px; color:#4a5568; border-bottom:1px solid #e2e8f0; }
        .details-table tbody tr:nth-child(even) td { background:#f8fafc; }

        /* TOTAUX */
        .totals-wrap { text-align:right; margin-bottom:32px; }
        .totals-table { display:inline-table; width:290px; border-collapse:collapse; }
        .totals-table td { padding:7px 14px; font-size:11px; border-bottom:1px solid #e2e8f0; }
        .totals-table td:first-child { color:#718096; text-align:left; }
        .totals-table td:last-child  { text-align:right; font-weight:600; color:#1a202c; }
        .row-final td { background:#212529 !important; border:none !important; padding:11px 14px !important; }
        .row-final td:first-child { color:#fff !important; font-size:12px !important; font-weight:700 !important; border-radius:4px 0 0 4px; }
        .row-final td:last-child  { color:#ffc800 !important; font-size:15px !important; font-weight:700 !important; border-radius:0 4px 4px 0; }

        /* NOTE */
        .note-box { background:#fffbeb; border:1px solid #fcd34d; border-left:3px solid #ffc800; border-radius:4px; padding:10px 14px; margin-bottom:28px; font-size:10px; color:#78350f; line-height:1.7; }

        /* SIGNATURES */
        .sig-wrap { width:100%; margin-bottom:32px; }
        .sig-box  { text-align:center; vertical-align:top; width:45%; }
        .sig-label2 { font-size:8px; font-weight:700; text-transform:uppercase; letter-spacing:1.5px; color:#a0aec0; margin-bottom:5px; }
        .sig-name { font-size:11px; font-weight:600; color:#4a5568; margin-bottom:48px; }
        .sig-line { border-top:1px solid #cbd5e0; width:80%; margin:0 auto; }
        .sig-caption { font-size:9px; color:#a0aec0; margin-top:4px; }

        /* FOOTER */
        .footer { border-top:1px solid #e2e8f0; padding-top:14px; text-align:center; }
        .footer p { font-size:9px; color:#a0aec0; line-height:1.9; }
        .footer strong { color:#718096; }

        .bottom-gold  { background:#ffc800; height:4px; width:100%; margin-top:24px; }
        .bottom-dark  { background:#212529; height:8px; width:100%; }

        /* QR placeholder */
        .qr-box { border:1px dashed #cbd5e0; border-radius:4px; width:56px; height:56px; display:inline-block; text-align:center; vertical-align:middle; font-size:7px; color:#a0aec0; padding-top:18px; }
